-- V1 baseline: the complete schema as it existed on the live dev database when
-- Flyway was adopted (generated by pg_dump from the Hibernate-managed schema plus
-- the hand-applied migrations recorded in CLAUDE.md).
-- Existing databases ABSORB this file via baseline-on-migrate (it is marked applied
-- without executing); a FRESH database executes it and gets the whole schema.
-- From V2 on, this directory is the ONLY way the schema changes.







-- Name: channel_participants; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.channel_participants (
    id bigint NOT NULL,
    joined_at timestamp(6) with time zone NOT NULL,
    channel_id bigint NOT NULL,
    user_id bigint NOT NULL
);


-- Name: channel_participants_id_seq; Type: SEQUENCE; Schema: public; Owner: -

ALTER TABLE public.channel_participants ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.channel_participants_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


