-- Name: channels; Type: TABLE; Schema: public; Owner: -

CREATE TABLE public.channels (
    id bigint NOT NULL,
    created_at timestamp(6) with time zone NOT NULL,
    name character varying(255) NOT NULL,
    type character varying(16) NOT NULL,
    updated_at timestamp(6) with time zone NOT NULL,
    dm_key character varying(41),
    owner_id bigint,
    CONSTRAINT channels_type_check CHECK (((type)::text = ANY ((ARRAY['TEXT'::character varying, 'VOICE'::character varying, 'DM'::character varying, 'GROUP_DM'::character varying])::text[])))
);


-- Name: channels_id_seq; Type: SEQUENCE; Schema: public; Owner: -

ALTER TABLE public.channels ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.channels_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


