    edited_at timestamp(6) with time zone,
    forward_author_id bigint,
    forward_author_name character varying(50),
    forward_created_at timestamp(6) with time zone,
    forward_origin_channel character varying(100),
    forward_origin_server character varying(100),
    forward_trusted boolean,
    replied_to_id bigint,
    forward_nested_reply text,
    attachments text
);


